// Generated by vibes-espmatter – the pages of the web interface and the app icon of their home screen apps.
#include "espm_web.h"
#include "espm_config.h"

#include <cstring>

// App icon (espm_icon.cpp), referenced by the pages and their web app manifests.
extern const char mesp_icon_svg[];
extern const uint8_t mesp_icon_png[];
extern const size_t mesp_icon_png_len;

// The pages, compiled from Svelte by the build server (EMBED_FILES): k_pages.
#include "espm_web_ui_pages.h"

/** It only changes with a firmware update; a day of caching is plenty. */
static esp_err_t send_icon(httpd_req_t *req, const char *type, const void *data, size_t len)
{
    httpd_resp_set_type(req, type);
    httpd_resp_set_hdr(req, "Cache-Control", "max-age=86400");
    return httpd_resp_send(req, (const char *)data, len);
}

static esp_err_t icon_svg_handler(httpd_req_t *req)
{
    return send_icon(req, "image/svg+xml", mesp_icon_svg, strlen(mesp_icon_svg));
}

static esp_err_t icon_png_handler(httpd_req_t *req)
{
    return send_icon(req, "image/png", mesp_icon_png, mesp_icon_png_len);
}

void mesp_web_ui_register_web()
{
    for (const auto &page : k_pages) mesp_web_add_page(page.path, page.start, page.end, page.manifest);
    mesp_web_add("/icon.svg", HTTP_GET, icon_svg_handler);
    mesp_web_add("/icon.png", HTTP_GET, icon_png_handler);
    // iOS asks for this when a page has no apple-touch-icon link.
    mesp_web_add("/apple-touch-icon.png", HTTP_GET, icon_png_handler);
}
